    "sparse-matrix-vector-multiplication-markdown-code-12": "#include <cuda_runtime.h>\n\n__global__ void spmv_kernel(\n    const float* A,\n    const float* x,\n    float* y,\n    int M,\n    int N\n) {\n    __shared__ float shared[256];\n\n    int row = blockIdx.x;\n    int tid = threadIdx.x;\n    float sum = 0.0f;\n\n    if (row < M) {\n        for (int col = tid; col < N; col += blockDim.x) {\n            float value = A[row * N + col];\n            if (value != 0.0f) {\n                sum += value * x[col];\n            }\n        }\n    }\n\n    shared[tid] = sum;\n    __syncthreads();\n\n    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {\n        if (tid < offset) {\n            shared[tid] += shared[tid + offset];\n        }\n        __syncthreads();\n    }\n\n    if (tid == 0 && row < M) {\n        y[row] = shared[0];\n    }\n}\n\n// A, x, y are device pointers\nextern \"C\" void solve(\n    const float* A,\n    const float* x,\n    float* y,\n    int M,\n    int N,\n    int nnz\n) {\n    (void)nnz;\n    constexpr int threadsPerBlock = 256;\n    spmv_kernel<<<M, threadsPerBlock>>>(A, x, y, M, N);\n    cudaDeviceSynchronize();\n}"
